import * as React from "react"

import { HugeiconsIcon, type IconSvgElement } from "@hugeicons/react"

import { FileEmptyIcon } from "./huge-icons"
import { cn } from "@/lib/utils"

/**
 * Every custom icon the project defines, in one place: code and file marks,
 * color-format marks, brand logos, package marks, and emoji helpers.
 *
 * Hugeicons glyphs are NOT defined here — the brand's set lives in
 * `@/icons/huge-icons` and renders through the `Icon` wrapper below.
 */

/** Raw Hugeicons icon data, as taken by `Icon` / `HugeiconsIcon`. */
export type IconData = IconSvgElement

type IconProps = React.ComponentProps<typeof HugeiconsIcon>

/** `HugeiconsIcon` with the app-wide default styling. */
export function Icon({ strokeWidth, className, ...props }: IconProps) {
  return (
    <HugeiconsIcon
      strokeWidth={strokeWidth}
      className={cn(
        "text-muted-foreground hover:text-foreground transition-colors",
        className
      )}
      {...props}
    />
  )
}

/** Props for the hand-drawn SVG icons below. */
